.bloc-s {
  text-align: center;
  padding-block: 0 30px;
  max-width: 700px;
  width: 100%;
  margin: auto;
}

.bloc-s h1 {
  color: black;
  margin: 0;
}

.bloc-s p {
  font-size: 15px;
  color: black;
  margin-top: 10px;
}

.jasja {
  height: 500px;
  overflow: auto;
}
.status-badge.green {
    background: #44ef55;
    color: white;
    padding: 2px 8px;
    border-radius: 12px;
    font-size: 12px;
    margin-left: 8px;
}

.staking-grid-wrapper {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
  justify-content: center;
  margin-top: 2rem;
}

.staking-card {
  background: #131a22;
  border-radius: 1.25rem;
  padding: 1.5rem;
  width: 300px;
  color: #fff;
  /* box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3); */
  transition: transform 0.3s ease;
}

.staking-card:hover {
  transform: translateY(-5px);
}

.staking-card-header {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.staking-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
}

.staking-duration-label {
  margin-top: 1rem;
  font-size: 0.875rem;
  color: #aaa;
}

.staking-durations {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 0.5rem;
}

.staking-duration-option {
  flex: 1;
  background: #333;
  border-radius: 8px;
  padding: 0.5rem;
  text-align: center;
  cursor: pointer;
  transition: background 0.2s ease;
}

.staking-duration-option.active {
  background: #7634dc;
  color: #ffffff;
  font-weight: bold;
}

.staking-note {
  font-size: 0.75rem;
  margin-top: 1rem;
  text-align: center;
  color: #888;
}

.staking-min {
  display: flex;
  justify-content: space-between;
  margin-top: 1rem;
  font-size: 0.875rem;
  color: #bbb;
}

.staking-min strong {
  font-weight: bold;
  color: #fff;
}

.staking-btn {
  margin-top: 1.5rem;
  width: 100%;
  padding: 0.75rem;
  background: #7634dc;
  color: #ffffff;
  border: none;
  border-radius: 10px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.3s ease;
}

.staking-btn:hover {
  background: #551daa;
}

.staking-bot-info {
  display: flex;
  flex-direction: row;
  gap: 1rem;
  margin-top: 1.5rem;
  padding: 1rem;
  border: 1px solid #333;
  border-radius: 1rem;
  background-color: #131a22;
}

.tickettable tr:hover {
  cursor: pointer;
  background-color: rebeccapurple !important;
}

.tickettable th,
.tickettable td {
  color: white !important;
  background-color: transparent !important;
}

.staking-bot-left,
.staking-bot-right {
  width: 50%;
  font-size: 0.85rem;
  line-height: 1.4;
  color: #ccc;
}

.staking-bot-left h4,
.staking-bot-right h4 {
  font-size: 1rem;
  color: #7634dc;
  margin-bottom: 0.5rem;
  margin-top: 0.75rem;
}

.staking-bot-left p,
.staking-bot-right p {
  margin-bottom: 0.5rem;
}

.custom-col {
  width: 100%;
  padding: 1rem 0;
}

.custom-card {
  border: 1px solid #333;
  border-radius: 12px;
  background: #131a22;
  color: #e0e0e0;
  overflow: hidden;
}

.custom-card-header {
  border-bottom: 1px solid #2c2c2c;
  padding: 1rem;
}

.custom-card-title {
  font-size: 1.2rem;
  font-weight: 600;
  margin: 0;
  color: #fff;
}

.custom-card-body {
  padding: 1rem;
}

.custom-loader {
  text-align: center;
  margin: 4rem 0;
}

.custom-loader-text {
  margin-top: 1rem;
  font-size: 1.1rem;
  color: #bbb;
}

.custom-transaction-grid {
  display: grid;
  gap: 1rem;
}

.custom-transaction-card {
  border-bottom: 1px solid #2e2e2e;
  padding: 1rem 0;
}

.custom-transaction-body {
  display: flex;
  flex-direction: column;
}

.custom-transaction-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.custom-transaction-col {
  flex-grow: 1;
}

.custom-transaction-col-auto {
  white-space: nowrap;
}

.custom-transaction-title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.3rem;
  color: #fff;
}

.custom-status-text {
  font-weight: 400;
  color: #999;
}

.custom-transaction-amount {
  font-size: 0.95rem;
  margin-bottom: 0.3rem;
  color: #ccc;
}

.custom-transaction-date-mobile,
.custom-transaction-date-desktop {
  font-size: 0.85rem;
  color: #888;
}

.custom-transaction-date-mobile {
  display: block;
}

.custom-transaction-date-desktop {
  display: none;
}

@media (min-width: 768px) {
  .custom-transaction-date-mobile {
    display: none;
  }

  .custom-transaction-date-desktop {
    display: block;
  }
}

.custom-empty-state {
  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.custom-empty-box {
  text-align: center;
  max-width: 300px;
}

.custom-empty-title {
  font-size: 1.2rem;
  font-weight: 500;
  color: #aaa;
}

/*  */
.investment-details {
  margin-top: 10px;
  padding: 12px;
  background-color: rgba(0, 0, 0, 0.1);
  border-radius: 6px;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 8px;
  font-size: 14px;
}

.detail-row:last-child {
  margin-bottom: 0;
}

.detail-label {
  font-weight: 500;
  color: #aaa;
}

.detail-value {
  text-align: right;
}

.profit {
  color: #4caf50;
  font-weight: 500;
}

.profit-mountain-chart {
  background: rgba(31, 41, 55, 0.4);
  border-radius: 12px;
  padding: 16px;
  border: 1px solid rgba(74, 85, 104, 0.3);
  box-shadow:
    0 4px 6px -1px rgba(0, 0, 0, 0.1),
    0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.end-trade-btn {
  background-color: #ef4444;
  color: white;
  padding: 8px 16px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  margin-top: 10px;
}

.end-trade-btn:disabled {
  background-color: #6b7280;
  cursor: not-allowed;
}

.status-badge.closed {
  background: #EF4444;
  color: white;
  padding: 2px 8px;
  border-radius: 12px;
  font-size: 12px;
  margin-left: 8px;
}