}

.this-model .modal-dialog {
    margin: 0;
    max-width: 600px;
    width: 100%;
}

.this-model .modal-content {
    border-radius: 10px;
    background-color: #fff;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    border: none;
}

.this-model .modal-header {
